customColumn1.onClick:
{{
  GetDocumentInboxFileLink.run({
    fileId:
      currentRow.fileId ||
      currentRow.id ||
      currentRow.ID,
    mode: "preview"
  }).then(() => {
    navigateTo(GetDocumentInboxFileLink.data.url, {}, "NEW_WINDOW");
  })
}}

