customColumn5.isDisabled:
{{(() => { const tableData = DocumentInboxTable.processedTableData || []; return tableData.length > 0 ? tableData.map((currentRow, currentIndex) => (
  !["UPLOADED", "UNDER_REVIEW", "DUPLICATE"].includes(
    currentRow.status || ""
  )
)) : 
  !["UPLOADED", "UNDER_REVIEW", "DUPLICATE"].includes(
    currentRow.status || ""
  )
 })()}}

