customColumn9.isDisabled:
{{(() => { const tableData = DocumentInboxTable.processedTableData || []; return tableData.length > 0 ? tableData.map((currentRow, currentIndex) => (
  String(currentRow.status || currentRow.Status || "").toUpperCase() !== "APPROVED" ||
  !!(currentRow.processedDocumentId || currentRow.processed_document_id)
)) : 
  String(currentRow.status || currentRow.Status || "").toUpperCase() !== "APPROVED" ||
  !!(currentRow.processedDocumentId || currentRow.processed_document_id)
 })()}}
